private final Map<Op, BiFunction<Ctx, Integer, Integer>> handlers =
        new EnumMap<>(Op.class);
{ handlers.put(Op.ADD, (ctx, v) -> ctx.acc() + v); handlers.put(Op.SUB, Ctx::sub); }

int dispatch(Op op, int arg) {
    var handler = handlers.get(op);
    if (handler == null) throw new UnknownOpException(op);
    return handler.apply(ctx, arg);
}
